const form = $('AHTR Clinical Form').first().json;
const profile = $('Find Funding Profile').first().json;
const patient = $('Fetch Patient Record').first().json;
const fees = $('Fetch Fee Schedule').all().map(i => i.json);
const pracItem = $('Fetch Practitioner').first();
const prac = pracItem ? (pracItem.json || {}) : {};
const history = $input.all().map(i => i.json)
  .filter(r => r.funder === 'workers_comp' || r.funder === 'ctp')
  .sort((a, b) => String(a.service_date).localeCompare(String(b.service_date)));

function f(key) { return form[key] || '-'; }
function p(key) { return prac[key] || ''; }
function clean(s) { return String(s || '').replace(/\s*\(TEST\)/gi, '').trim(); }
function row(label, value) { return '<tr><th style="text-align:left;width:280px">' + label + '</th><td>' + (value || '-') + '</td></tr>'; }
function table(rows) { return '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;margin-bottom:12px">' + rows + '</table>'; }
function dmy(iso) {
  const s = String(iso || '').slice(0, 10);
  const pt = s.split('-');
  return pt.length === 3 ? pt[2] + '/' + pt[1] + '/' + pt[0] : (iso ? String(iso) : '');
}

const delivered = history.filter(r => r.status === 'validated' || r.status === 'paid');
let totalConsults = 0;
for (const d of delivered) { totalConsults += Number(d.quantity) || 0; }
const firstDate = delivered.length ? delivered[0].service_date : '';

const feeMap = {};
for (const fe of fees) { feeMap[String(fe.item_code).trim().toUpperCase()] = fe; }
const lastDelivered = delivered.length ? delivered[delivered.length - 1] : null;
const svcCode = lastDelivered ? String(lastDelivered.support_item_number || '').toUpperCase() : '';
const feeRow = svcCode ? feeMap[svcCode] : null;
const sessionsN = Number(form['Number of sessions requested']) || 0;
const costPer = feeRow ? Number(feeRow.rate) : null;
const totalCost = (costPer !== null && sessionsN > 0) ? (costPer * sessionsN) : null;

const claimDigits = String(profile.claim_number || '').replace(/[^0-9]/g, '');
const requestNo = 'AHTR-' + $today.toFormat('yyyyLLdd') + '-' + (claimDigits.slice(-4) || '0000');

const outcomeCurrent = f('Current outcome measure score');
const outcomeInitial = profile.outcome_initial_score || outcomeCurrent;
const outcomePrevious = profile.outcome_previous_score || '';

const disciplineMap = {
  'Physiotherapy': 'Physiotherapist',
  'Chiropractic': 'Chiropractor',
  'Osteopathy': 'Osteopath',
  'Psychology': 'Psychologist',
  'Exercise physiology': 'Accredited Exercise Physiologist',
  'Counselling': 'Counsellor'
};
const disciplinePdf = disciplineMap[form['Allied health discipline']] || 'Other (please specify)';

const asstRaw = form['Assistance requested from the insurer (optional)'];
const asstList = Array.isArray(asstRaw) ? asstRaw : (asstRaw && asstRaw !== 'None' ? [String(asstRaw)] : []);
const asstJoined = asstList.join(', ');
const asstLower = asstJoined.toLowerCase();
const asstDirect = asstLower.includes('direct contact') ? 'Yes' : '';
const asstCase = asstLower.includes('case conference') ? 'Yes' : '';
const asstCollab = asstLower.includes('collaborative') ? 'Yes' : '';
const caseWho = form['Case conference - who with (optional)'] || '';
const goalsRaw = form['Achievement of previous goals (optional)'] || 'First request under this approval';
const goalsBox = goalsRaw === 'First request under this approval' ? 'N/A' : goalsRaw;
const riskApplied = (form['Risk screening tool name (optional)'] && form['Risk screening tool name (optional)'] !== 'Not applied') ? 'Yes' : 'No';
const collabBox = form['Developed collaboratively with the injured person?'] || '';
const posDesc = form['Copy of position description/work duties held? (optional)'] || '';

let historyRows = '';
for (const h of history) {
  historyRows += '<tr><td>' + h.service_date + '</td><td>' + h.support_item_number + '</td><td>' + h.status + '</td><td>$' + Number(h.total).toFixed(2) + '</td></tr>';
}
if (!historyRows) historyRows = '<tr><td colspan="4">No prior treatment recorded</td></tr>';

let html = '<h1>Allied Health Treatment Request (AHTR)</h1>';
html += '<p><i>Structured per the SIRA Allied Health Treatment Request. Clinical sections authored by the treating practitioner; administrative data drawn from practice records.</i></p>';

html += table(
  row('Request number', requestNo) +
  row('Date of request', $today.toFormat('yyyy-MM-dd')) +
  row('Date services first commenced', firstDate || '-') +
  row('Total number of consultations to date', String(totalConsults)) +
  row('Allied health discipline', f('Allied health discipline')) +
  row('Referred by', form['Referred by (optional)'] || profile.referred_by || '-') +
  row('Referrer phone', form['Referrer phone number (optional)'] || '-')
);

html += '<h2>Section 1 — Injured person details</h2>';
html += table(
  row('Name', profile.patient_name) +
  row('Date of birth', patient.date_of_birth || '-') +
  row('Pre-injury occupation', patient.occupation || '-') +
  row('Pre-injury work hours per week', form['Pre-injury work hours per week (optional)'] || '-') +
  row('Claim number', profile.claim_number) +
  row('Date of injury/accident', profile.date_of_injury || '-')
);

html += '<h2>Section 2 — Clinical assessment</h2>';
html += table(
  row('Compensable injury or illness', f('Compensable injury or illness')) +
  row('Current clinical signs and symptoms', f('Current clinical signs and symptoms')) +
  row('Risk screening applied', riskApplied) +
  row('Risk screening tool', form['Risk screening tool name (optional)'] || 'Not applied') +
  row('Risk screening date', form['Risk screening date administered (optional)'] ? dmy(form['Risk screening date administered (optional)']) : '-') +
  row('Risk screening score/comment', form['Risk screening score/comment (optional)'] || '-') +
  row('Pre-existing conditions', form['Pre-existing conditions relevant to the injury (optional)'] || 'Nil relevant') +
  row('Copy of position description/work duties held', posDesc || '-') +
  row('Pre-injury capacity — work', f('Pre-injury capacity - work')) +
  row('Pre-injury capacity — usual activities', f('Pre-injury capacity - usual activities')) +
  row('Current capacity — work', f('Current capacity - work')) +
  row('Current capacity — usual activities', f('Current capacity - usual activities'))
);
html += '<h3>Standardised outcome measures</h3>';
html += table(
  row('Outcome measure', f('Standardised outcome measure name')) +
  row('Initial score', outcomeInitial + (profile.outcome_initial_score ? '' : ' (baseline — first request)')) +
  row('Previous score', outcomePrevious || '-') +
  row('Current score', outcomeCurrent) +
  row('Interpretation of scores', f('Interpretation of scores'))
);

html += '<h2>Section 3 — Barriers to recovery and strategies</h2>';
html += table(
  row('Barriers identified', f('Barriers to recovery')) +
  row('Strategies to address barriers', f('Strategies to address barriers')) +
  row('Assistance requested', asstJoined || 'None') +
  row('Case conference — who with', caseWho || '-')
);

html += '<h2>Section 4 — Treatment plan</h2>';
html += table(
  row('Achievement of previous goals', goalsRaw) +
  row('Work goal', f('Work goal')) +
  row('Activity/participation goal', f('Activity/participation goal')) +
  row('Self-management strategies', f('Self-management strategies')) +
  row('Evidence-based intervention approach and rationale', f('Evidence-based intervention approach and rationale')) +
  row('Anticipated discharge date', f('Anticipated discharge date')) +
  row('Developed collaboratively with the injured person', collabBox || '-')
);

html += '<h2>Section 5 — Service requested</h2>';
html += table(
  row('Service type', f('Service requested')) +
  row('Number of sessions', f('Number of sessions requested')) +
  row('Frequency / timeframe', f('Frequency / timeframe')) +
  row('Service code', svcCode || '-') +
  row('Cost per session', costPer !== null ? '$' + costPer.toFixed(2) : '-') +
  row('Total cost', totalCost !== null ? '$' + totalCost.toFixed(2) : '-')
);

html += '<h2>Section 6 — Practitioner details</h2>';
html += table(
  row('Treating practitioner', clean(p('practitioner_name')) || '[Set the default row in the practitioners table]') +
  row('AHPRA number', p('ahpra_number')) +
  row('SIRA approval number', p('sira_approval_number')) +
  row('Practice name', clean(p('practice_name'))) +
  row('Practice email', p('practice_email')) +
  row('Practitioner email', p('practitioner_email')) +
  row('Phone / fax', (p('phone') || '-') + ' / ' + (p('fax') || '-')) +
  row('Suburb / state / postcode', (p('suburb') || '-') + ' ' + (p('state') || '') + ' ' + (p('postcode') || '')) +
  row('Best time to contact', p('best_contact'))
);

html += '<h2>Appendix — Treatment delivered under this claim</h2>';
html += '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Date</th><th>Service</th><th>Status</th><th>Amount</th></tr>' + historyRows + '</table>';
html += '<p>Please review and confirm approval to the clinic, quoting a new approval reference.</p>';

const pdf = {
  req_no: requestNo,
  date_req: dmy($today.toFormat('yyyy-MM-dd')),
  date_first: firstDate ? dmy(firstDate) : '',
  consults: String(totalConsults),
  discipline: disciplinePdf,
  referred: form['Referred by (optional)'] || profile.referred_by || '',
  ref_phone: form['Referrer phone number (optional)'] || '',
  name: profile.patient_name || '',
  dob: dmy(patient.date_of_birth),
  occupation: patient.occupation || '',
  hours: form['Pre-injury work hours per week (optional)'] || '',
  claim: profile.claim_number || '',
  injury_date: dmy(profile.date_of_injury),
  injury: f('Compensable injury or illness'),
  symptoms: f('Current clinical signs and symptoms'),
  risk_tool: form['Risk screening tool name (optional)'] || '',
  risk_date: form['Risk screening date administered (optional)'] ? dmy(form['Risk screening date administered (optional)']) : '',
  risk_score: form['Risk screening score/comment (optional)'] || '',
  preexisting: form['Pre-existing conditions relevant to the injury (optional)'] || 'Nil relevant',
  cap_pre_work: f('Pre-injury capacity - work'),
  cap_pre_act: f('Pre-injury capacity - usual activities'),
  cap_cur_work: f('Current capacity - work'),
  cap_cur_act: f('Current capacity - usual activities'),
  som_name: f('Standardised outcome measure name'),
  som_init: outcomeInitial,
  som_prev: outcomePrevious,
  som_cur: outcomeCurrent,
  interp: f('Interpretation of scores'),
  barriers: f('Barriers to recovery'),
  strategies: f('Strategies to address barriers'),
  work_goal: f('Work goal'),
  act_goal: f('Activity/participation goal'),
  selfman: f('Self-management strategies'),
  intervention: f('Evidence-based intervention approach and rationale'),
  sessions: f('Number of sessions requested'),
  discharge: dmy(form['Anticipated discharge date']),
  service: f('Service requested'),
  frequency: f('Frequency / timeframe'),
  svc_code: svcCode,
  cost_per: costPer !== null ? costPer.toFixed(2) : '',
  total_cost: totalCost !== null ? totalCost.toFixed(2) : '',
  risk_applied: riskApplied,
  pos_desc: posDesc,
  goals_box: goalsBox,
  collab: collabBox,
  asst_direct: asstDirect,
  asst_case: asstCase,
  asst_collab: asstCollab,
  case_who: caseWho,
  pr_name: clean(p('practitioner_name')),
  pr_ahpra: p('ahpra_number'),
  pr_sira: p('sira_approval_number'),
  pr_practice: clean(p('practice_name')),
  pr_prac_email: p('practice_email'),
  pr_email: p('practitioner_email'),
  pr_phone: p('phone'),
  pr_fax: p('fax'),
  pr_suburb: p('suburb'),
  pr_state: p('state'),
  pr_postcode: p('postcode'),
  pr_best: p('best_contact')
};

return [{ json: {
  html: html,
  pdf: pdf,
  insurer_email: profile.insurer_email || '',
  claim_number: profile.claim_number || '',
  patient_name: profile.patient_name || '',
  sessions_requested: form['Number of sessions requested'] || '',
  outcome_name: form['Standardised outcome measure name'] || '',
  outcome_current: outcomeCurrent,
  outcome_initial_new: profile.outcome_initial_score || outcomeCurrent
} }];
